/**
 * The array-CGH page's quick guide: seven steps, one annotated screenshot each (synthetic demo data, regenerated by
 * docs/cgh-demo/make-guide-shots.cjs). Esc or × closes it; the store's `help` keeps Esc from closing the page too.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { cgh, useCgh } from './cghStore';
import step1 from '../../assets/cgh-guide/step1.webp';
import step2 from '../../assets/cgh-guide/step2.webp';
import step3 from '../../assets/cgh-guide/step3.webp';
import step3b from '../../assets/cgh-guide/step3b.webp';
import step4 from '../../assets/cgh-guide/step4.webp';
import step5 from '../../assets/cgh-guide/step5.webp';
import step6 from '../../assets/cgh-guide/step6.webp';

const B = ({ children }: { children: ReactNode }) => <b className="font-semibold text-slate-900">{children}</b>;
const STEPS: { title: string; img: string; body: ReactNode }[] = [
  { title: 'Add samples', img: step1, body: <>
    <B>Add samples</B>, or drop files on the page. Read: CytoGenomics interval tables (.txt), other tables of calls (.txt, .tsv, .csv, .xlsx), BED, SV / CNV VCF (.vcf, .vcf.gz), and zip files of them (one patient per zip). Files are read in the page, never sent anywhere.
    <br />A table whose columns are not recognised opens <B>Which column is which?</B>: pick the chromosome, start, end and type columns once; the choice is remembered for tables with the same column names.</> },
  { title: 'The import question', img: step2, body: <>
    Calls with fewer probes, or smaller, than the <B>minimum number of probes</B> (3 by default) and the <B>minimum size</B> (slider, or a typed value with its unit) are neither listed nor annotated; both can be changed in the list afterwards.
    Set each patient's <B>sex</B> (read from the file when it says so). The 200 largest calls passing the minimums are annotated first, the others on demand (<B>annotate</B>).
    Then <B>Analyse</B>.</> },
  { title: 'The table', img: step3, body: <>
    One tab per patient, and <B>All patients</B> in one table. Click a call: its detail (genes, dosage, DGV Gold, priority, note) opens under its row and the call is drawn in the browser below the table; <B>↑ ↓</B> go to the next call, a second click on the row folds the detail.
    A patient's calls under the minimums are counted on a row of their own: <B>+ N more calls … under the minimums</B> lists them.</> },
  { title: 'Filters', img: step4, body: <>
    <B>probes ≥</B>, <B>all / losses / gains</B>, <B>size</B>, <B>class</B> (classified or not), and under <B>More filters</B>: <B>series</B> (how many other loaded patients carry the call), <B>lab list</B>, <B>hide suppressed</B> (calls marked Suppress in CytoGenomics).
    Search a gene, a band (16p11) or a chromosome; order by <B>position</B> or <B>priority</B> (HIGH first).</> },
  { title: 'The lab benign list', img: step5, body: <>
    <B>Lab benign CNVs (BED)…</B> loads the laboratory's list of benign CNVs (chrom, start, end, a name saying del / dup, else both types). It is kept in this browser for the next sessions; × removes it.
    A call sharing 80 % of itself or more with an entry of its type is tagged <B>lab benign</B>, and an unclassified one gets <B>→ Benign?</B>: a suggestion, nothing is classified by itself.</> },
  { title: 'Interpret: the call in the browser', img: step3b, body: <>
    Before classifying, read the call: its detail under its row says why its <B>priority</B> (the rules it meets), its genes (HI, TS, LOEUF, PanelApp, exons cut and frame), the ClinGen regions, DGV Gold and AChro-Puce it matches, its mosaic estimate and its recurrence in the series. The call clicked is drawn under the table, in the SV browser's own browser, as a deletion or a duplication on the file's build (GRCh37): the call shaded through the tracks, its breakpoints in bold, its array ISCN on the line above.
    Tracks: genes (coloured by LOEUF, impact or inheritance), <B>DGV Gold</B>, <B>ClinVar SV / SNV</B>, <B>AChro-Puce</B>, a <B>Gene panel (PanelApp)</B>; then the reference and the rebuilt chromosome. Drag to pan, Ctrl / ⌘ + scroll to zoom, hover a gene for its card.</> },
  { title: 'Classify, note, export', img: step6, body: <>
    Choose the class in the <B>Classification</B> column; <B>✎</B> adds a note on the call. Classes and notes stay in this tab only:
    <B> Export classified table</B> (• when there is something to export) writes each file back as it came, with the classes in its Classification column and the notes in a Comment column (<i>name</i>.classified.txt; a BED gets two last columns, a VCF INFO CGH_CLASS / CGH_NOTE, an .xlsx is written as tab-separated text).</> },
];

/** "? Quick guide" in the page's bar */
export function CghGuideButton() {
  return <button onClick={() => cgh.setHelp(true)} className="ml-auto inline-flex items-center gap-1.5 h-7 px-2.5 rounded-lg text-xs font-medium border bg-bar-ctrl border-bar-line text-bar-text hover:border-accent-300" title="A short guide to this page, step by step">? Quick guide</button>;
}

export function CghGuide() {
  const open = useCgh().help;
  const [i, setI] = useState(0);
  useEffect(() => {
    if (!open) return;
    // capture: before the page's own Esc
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { e.stopPropagation(); cgh.setHelp(false); }
      else if (e.key === 'ArrowRight') setI(k => Math.min(STEPS.length - 1, k + 1));
      else if (e.key === 'ArrowLeft') setI(k => Math.max(0, k - 1));
    };
    window.addEventListener('keydown', onKey, true);
    return () => window.removeEventListener('keydown', onKey, true);
  }, [open]);
  if (!open) return null;
  const s = STEPS[i], btn = 'h-[30px] px-3 rounded-[6px] border border-slate-200 text-slate-700 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed';
  return (
    <div className="fixed inset-0 z-[80] bg-black/40 flex items-start justify-center p-3 overflow-y-auto" role="dialog" aria-modal="true" aria-label="Quick guide" data-cgh-guide
      onClick={e => { if (e.target === e.currentTarget) cgh.setHelp(false); }}>
      <div className="bg-white rounded-xl shadow-2xl border border-slate-200 w-full max-w-[min(1240px,96vw)] text-slate-900 text-sm mt-6">
        <div className="px-4 pt-3 pb-2 border-b border-slate-200 flex items-start gap-3">
          <div>
            <div className="font-bold text-base">Array-CGH: quick guide</div>
            <div className="text-[12.5px] text-slate-500 mt-0.5">Step {i + 1} of {STEPS.length}: {s.title}. Screenshots of invented demo data.</div>
          </div>
          <button onClick={() => cgh.setHelp(false)} className="ml-auto text-slate-400 hover:text-slate-700 text-lg leading-none px-1" aria-label="Close the guide" title="Close (Esc)">×</button>
        </div>
        <div className="px-4 py-3 space-y-3">
          <div className="text-[14.5px] leading-6 text-slate-700 max-w-[1100px]">{s.body}</div>
          <img src={s.img} alt={`Step ${i + 1}: ${s.title}`} className="block w-full max-w-[1200px] mx-auto rounded-lg border border-slate-200" />
        </div>
        <div className="px-4 py-2.5 border-t border-slate-200 flex items-center gap-2">
          <div className="flex items-center gap-1.5" role="tablist" aria-label="Steps">
            {STEPS.map((x, k) => <button key={x.title} role="tab" aria-selected={k === i} onClick={() => setI(k)} title={`${k + 1}. ${x.title}`} aria-label={`Step ${k + 1}: ${x.title}`}
              className={`w-2.5 h-2.5 rounded-full ${k === i ? 'bg-accent-600' : 'bg-slate-300 hover:bg-slate-400'}`} />)}
          </div>
          <span className="ml-auto" />
          <button className={btn} disabled={i === 0} onClick={() => setI(i - 1)}>← Previous</button>
          {i < STEPS.length - 1
            ? <button autoFocus className="h-[30px] px-4 rounded-[6px] bg-accent-600 text-white font-semibold hover:bg-accent-700" onClick={() => setI(i + 1)}>Next →</button>
            : <button className="h-[30px] px-4 rounded-[6px] bg-accent-600 text-white font-semibold hover:bg-accent-700" onClick={() => cgh.setHelp(false)}>Done</button>}
        </div>
      </div>
    </div>
  );
}
